function productRows(){const master=masterIndex(),rows=new Map(),blank=target=>({...target,spend:0,sales:0,orders:0,units:0,net:0,quantity:0,refunds:0,costs:[],inventory:[],adsRecords:0,financeRecords:0}),add=(record,field)=>{const target=resolveMaster(master,record);if(!target)return;const current=rows.get(target.productId)||blank(target);if(field==='cost')current.costs.push(record);if(field==='inventory')current.inventory.push(record);rows.set(target.productId,current)};for(const r of adsRows()){const target=resolveMaster(master,r);if(!target)continue;const current=rows.get(target.productId)||blank(target);current.spend+=Number(r.spend==null?r.cost:r.spend)||0;current.sales+=+r.sales||0;current.orders+=+r.orders||0;current.units+=+r.units||0;current.adsRecords+=1;rows.set(target.productId,current)}for(const r of financeRows()){const target=resolveMaster(master,r);if(!target)continue;const current=rows.get(target.productId)||blank(target);if(r.type!=='Transfer')current.net+=+r.total||0;current.quantity+=Math.max(0,+r.quantity||0);if(r.type==='Refund')current.refunds+=Math.abs(+r.quantity||0);current.financeRecords+=1;rows.set(target.productId,current)}for(const r of load('costs'))add(r,'cost');for(const r of load('inventory'))add(r,'inventory');return[...rows.values()].map(r=>{const unitCost=r.costs.length?r.costs.reduce((s,x)=>s+x.unitCost+x.inboundCost,0)/r.costs.length:0,cogs=unitCost*(r.quantity||r.units||0),contribution=r.net-cogs-r.spend,inv=[...r.inventory].sort((a,b)=>a.date.localeCompare(b.date)).at(-1),breakEvenMetric=breakEvenAcosMetric({operatingNet:r.net,cogs,adSales:r.sales,hasFinance:r.financeRecords>0,hasCost:r.costs.length>0,hasAds:r.adsRecords>0});return{...r,unitCost,cogs,contribution,margin:r.financeRecords>0&&r.net?contribution/r.net:null,breakEvenAcos:breakEvenMetric.value,breakEvenMetric,available:inv?.available??null}}).sort((a,b)=>b.contribution-a.contribution)}
function refundOpportunityRows(rows=productRows()){return rows.filter(row=>row.refunds>0).map(row=>({product:row.product,sku:row.sku,refundUnits:row.refunds,unitCost:row.unitCost,estimatedCostExposure:row.unitCost?row.refunds*row.unitCost:null})).sort((a,b)=>(b.estimatedCostExposure||0)-(a.estimatedCostExposure||0))}
function refundOpportunityPanel(){const rows=refundOpportunityRows();return rows.length?`<div class="card top-gap"><div class="card-head"><div class="card-title"><h3>Refund cost exposure review</h3><small>Imported Unified refund rows joined through Product Master. This is a follow-up queue, not an Amazon reimbursement eligibility decision.</small></div></div>${table(['Product','SKU','Refund units','Imported unit cost','Cost exposure'],rows.map(row=>`<tr><td class="left"><b>${esc(row.product)}</b></td><td>${esc(row.sku||'—')}</td><td>${integer(row.refundUnits)}</td><td>${row.unitCost?money(row.unitCost):'—'}</td><td>${row.estimatedCostExposure==null?'—':money(row.estimatedCostExposure)}</td></tr>`))}</div>`:`<div class="notice-banner top-gap">Refund opportunity review unavailable: import Unified refund rows and map them in Product Master.</div>`}
