function renderProduct360(){const rows=productRows(),unmapped=unmappedRecords();return`<div class="growth-actions"><div><b>Product economics</b><small>Explicit Product Master joins across Ads, Unified transactions, COGS and inventory.</small></div><div><button class="btn" data-growth-import="costs">Import COGS</button> <button class="btn" data-growth-import="inventory">Import Inventory</button> <button class="btn secondary" data-growth-page="product-master">Open Product Master</button></div></div>${!load('product-master').length?'<div class="notice-banner"><b>Product Master required.</b> Product 360 will not heuristically join product labels. Import explicit SKU/ASIN mappings first.</div>':''}${unmapped.length?`<div class="notice-banner"><b>${integer(unmapped.length)} unmapped identities excluded.</b> Open Product Master to resolve them before relying on cross-source economics.</div>`:''}${!load('costs').length?'<div class="notice-banner">Contribution excludes COGS until a cost CSV is imported.</div>':''}${rows.length?table(['Product','SKU','ASIN','Ad Spend','Ad Sales','Operating Net','Units','Unit Cost','COGS','Contribution','Margin','Available'],rows.map(r=>`<tr><td class="left"><b>${esc(r.product)}</b></td><td>${esc(r.sku||'—')}</td><td>${esc(r.asin||'—')}</td><td>${money(r.spend)}</td><td>${money(r.sales)}</td><td>${money(r.net)}</td><td>${integer(r.quantity||r.units)}</td><td>${r.unitCost?money(r.unitCost):'—'}</td><td>${r.unitCost?money(r.cogs):'—'}</td><td>${r.unitCost?money(r.contribution):'—'}</td><td>${r.unitCost?pct(r.margin):'—'}</td><td>${r.available==null?'—':integer(r.available)}</td></tr>`)):empty('No explicitly mapped product evidence','Import a Product Master CSV, then map the identifiers present in Ads, Unified, cost and inventory files.','product-master','Open Product Master')}`}
